create table membership_plans (id uuid primary key,code varchar(80) not null,name varchar(160) not null,reservation_limit integer not null check(reservation_limit>=0),version integer not null,valid_from timestamptz not null,valid_until timestamptz,active boolean not null,legacy_id varchar(80),constraint uq_membership_plan_version unique(code,version));
create table membership_assignments (id uuid primary key,user_id varchar(200) not null,plan_id uuid not null,plan_code varchar(80) not null,plan_version integer not null,reservation_limit integer not null,valid_from timestamptz not null,valid_until timestamptz,active boolean not null,idempotency_key varchar(200) not null unique,request_hash varchar(200) not null,legacy_user_id varchar(80));
create index idx_membership_assignment_user on membership_assignments(user_id,active,valid_from);
create table membership_history (id uuid primary key,user_id varchar(200) not null,assignment_id uuid not null,action varchar(40) not null,occurred_at timestamptz not null,correlation_id varchar(120) not null);
create table membership_outbox (event_id uuid primary key,event_type varchar(120) not null,event_version integer not null,occurred_at timestamptz not null,correlation_id varchar(120) not null,causation_id varchar(120) not null,producer varchar(80) not null,payload_json text not null,published boolean not null default false);
create index idx_membership_outbox_pending on membership_outbox(published,occurred_at);
create table membership_inbox (event_id uuid primary key,event_type varchar(120) not null,received_at timestamptz not null);
